const input = $json.body ?? $json;
const clean = (value) => typeof value === 'string' ? value.trim() : '';
const name = clean(input.name);
const email = clean(input.email).toLowerCase();
const phone = clean(input.phone);
const serviceKey = clean(input.service).toLowerCase();
const message = clean(input.message);

if (!name) throw new Error('Name is required');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
  throw new Error('A valid email is required');
}

const routes = {
  'airport transfer': { priority: 'Urgent', owner: 'Operations', minutes: 10 },
  'tour booking': { priority: 'High', owner: 'Sales — Tours', minutes: 15 },
  'vacation rental': { priority: 'High', owner: 'Reservations', minutes: 15 },
  'general inquiry': { priority: 'Normal', owner: 'Customer Care', minutes: 30 },
};
const route = routes[serviceKey] ?? routes['general inquiry'];
const receivedAt = new Date();
const responseDueAt = new Date(receivedAt.getTime() + route.minutes * 60000);

return [{ json: {
  lead_id: `LEAD-${receivedAt.getTime()}`,
  received_at: receivedAt.toISOString(),
  name, email, phone,
  service: serviceKey ? serviceKey.replace(/\b\w/g, c => c.toUpperCase()) : 'General Inquiry',
  message,
  priority: route.priority,
  assigned_owner: route.owner,
  response_target_minutes: route.minutes,
  response_due_at: responseDueAt.toISOString(),
  status: 'New'
} }];

